# POST /api/sheets/{sheetId}/claims/{claimId}/split — split an amount (body {amount, user}), more than
# 0.00 and less than the claim's amount, off an OPEN claim. The claim keeps the rest of its amount and is
# unbound from any figure a statement bound it to; a new OPEN claim with the amount split off, the same
# date and note, the next number, opened by the user, split-from the claim's number and due by its date
# plus the terms in force on that date (fixed now) is listed as its person's newest claim. Refused (400)
# when the amount does not parse or is out of range, the claim is not OPEN (PENDING, deferred on the
# sheet's today, settled, ...) or not on the sheet, its due-by falls in a closed period, or the sheet's
# permission matrix does not allow the user's role to open a claim; nothing is stored then. A stored
# split is recorded in the audit file as CLAIM_SPLIT, then CLAIM_OPENED for the new claim.
validate:
  class: net.officefloor.hq.app.claim.ValidateSplit
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: checkClaim
checkClaim:
  class: net.officefloor.hq.app.claim.CheckClaimPeriod
  govern: [ transaction ]
  next: checkSplit
checkSplit:
  class: net.officefloor.hq.app.claim.CheckSplit
  govern: [ transaction ]
  next: snapshot
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplySplit
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimSplit
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
# POST /api/sheets/{sheetId}/claims/{claimId}/status — move a claim to a new status (body
# {status, user, review, reason}): DRAFT to OPEN, OPEN to SETTLED, DRAFT, OPEN or PENDING to VOID,
# and SETTLED to VOID by a steward within 7 days of its settling (its status log's SETTLED date); DRAFT
# to DELETED (deleted: it counts nowhere), and DELETED back to DRAFT (restored) only on the sheet's today it
# was deleted on (its status log's last DELETED date).
# A clerk (any user not assigned steward) settling a claim whose due is above the sheet's clerk limit
# sends it to PENDING instead. A steward reviews a PENDING claim (review true): status SETTLED approves
# it (not by the user who opened it or last edited it), status OPEN with a reason rejects it. Refused (400) for any
# other change, when the sheet's permission matrix (perm-open, perm-settle, perm-void; by default a
# clerk or a steward) does not allow the user's role to open, settle or void, when settling or approving a claim with no proofs whose due is above the proof threshold
# in force on its date, when opening a claim with an empty note whose due is above the note threshold
# in force on its date (both checked before the clerk limit, so it never goes to PENDING), when the user who opened the claim or last edited it (claim form or amount entry) tries to settle or approve it, when the claim is not on
# the sheet, or when its due-by falls in a closed period, or when opening a DRAFT whose due-by falls in a period
# with a cap while its person already has that many OPEN or PENDING claims due in it; nothing is stored then. Opening records the
# user as the claim's opened-by; a claim whose due is above the review threshold in force on its date goes to REVIEW (no
# number yet, CLAIM_REVIEW) instead of OPEN, and only a steward's review (status OPEN, review true) moves it on: CLAIM_REVIEWED,
# then CLAIM_OPENED with its number. A REVIEW claim may otherwise only be voided.
# A stored change is recorded in the audit file as CLAIM_OPENED,
# CLAIM_PENDING, CLAIM_SETTLED, CLAIM_APPROVED, CLAIM_REJECTED, CLAIM_VOIDED, CLAIM_DELETED or CLAIM_RESTORED (with reversed=<the
# frozen figure> when a SETTLED claim is voided). While the sheet has void reasons, a void needs one of
# them as its reason (refused otherwise); it is kept on the claim and CLAIM_VOIDED ends with reason=<it>.
validate:
  class: net.officefloor.hq.app.claim.ValidateStatus
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: checkClaim
checkClaim:
  class: net.officefloor.hq.app.claim.CheckClaimPeriod
  govern: [ transaction ]
  next: checkLimit
checkLimit:
  class: net.officefloor.hq.app.claim.CheckClerkLimit
  govern: [ transaction ]
  next: snapshot
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyStatus
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimStatus
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

/** Body of an OPEN claim's split, as sent: the amount to split off it and who splits it. */
public record SplitRequest(String amount, String user) {
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.util.regex.Pattern;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSplit {
    /** A number with up to two decimals. */
    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?");

    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody SplitRequest request, Out<SplitInput> body,
            RoleStore roles) throws InvalidSheetException {
        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidSheetException("The amount must be a number with up to two decimals");
        }
        BigDecimal value = new BigDecimal(amount).setScale(2);
        if (value.signum() <= 0) {
            throw new InvalidSheetException("The amount split off must be more than 0.00");
        }
        body.set(new SplitInput(value, request.user()));
    }
}
package net.officefloor.hq.app.claim;

/** A stored split: the new OPEN claim split off the claim. */
public record Split(Claim into) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Val;

/** Refuses splitting a claim that is not OPEN (a PENDING one too), one deferred on the sheet's today, an
 *  amount not less than the claim's, or a split by a role the sheet's permission matrix does not allow to
 *  open a claim (the new claim is theirs to open). */
public class CheckSplit {
    public void check(@Val SplitInput input, @Val Claim claim, RoleStore roles, SettingStore settings, SheetStore sheets)
            throws InvalidSheetException {
        if (claim.getStatus() != ClaimStatus.OPEN) {
            throw new InvalidSheetException("Only an OPEN claim can be split");
        }
        if (claim.isDeferredOn(sheets.today(claim.getSheetId()))) {
            throw new InvalidSheetException("A deferred claim cannot be split until " + claim.getDeferredUntil());
        }
        if (input.amount().compareTo(claim.getAmount()) >= 0) {
            throw new InvalidSheetException("The amount split off must be less than the claim's " + claim.getAmount());
        }
        CheckClerkLimit.refuseUnpermitted(ClaimStatus.OPEN, claim.getSheetId(),
                roles.find(claim.getSheetId(), input.user()), settings);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;

/** A validated split: the amount (two decimals, more than 0.00) to split off the claim and who splits it. */
public record SplitInput(BigDecimal amount, String user) {
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.HolidayStore;
import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Splits the amount off the OPEN claim, which keeps the rest unbound from any statement figure, into a new
 *  OPEN claim of the same date and note, numbered next in the period of its own due-by (see {@link Numbering}), opened by the user, due by
 *  the business day its person's own terms (else the grade's they have, else the sheet's, each in force on the sheet's today, when it is split off) after its date, fixed
 *  now (a late entry when the period that due-by falls in is soft-closed), and logged as OPEN by the user. Refused when another user moved the claim on first. */
public class ApplySplit {
    public void apply(@Val SplitInput input, @Val Claim claim, ClaimStore store, PersonStore people, SettingStore settings,
            SheetStore sheets, PeriodStore periods, ClaimLogStore log, HolidayStore holidays,
            Out<Split> split) throws InvalidSheetException {
        if (!store.shrink(claim, claim.getAmount().subtract(input.amount()))) {
            throw new InvalidSheetException("Only an OPEN claim can be split");
        }
        String sheetId = claim.getSheetId();
        Person person = people.find(sheetId, claim.getPersonId());
        int terms = SaveClaimAdded.termsOf(person, settings);
        LocalDate dueBy = holidays.businessDaysAfter(sheetId, claim.getDate(), terms);
        String number = Numbering.next(sheetId, dueBy, store, settings, sheets, periods);
        Claim into = store.addSplit(claim, input.amount(), number, input.user(), dueBy, terms);
        if (periods.softOn(sheetId, dueBy)) {
            store.markLateEntry(into);
        }
        log.record(into, input.user());
        split.set(new Split(into));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.plugin.variable.Val;

/** Records a stored split: CLAIM_SPLIT sheet=<id> by=<user> person=<name> amount=<remaining 0.00>
 *  date=<yyyy-mm-dd> number=<n> into=<new number>, then CLAIM_OPENED for the new claim as an opening
 *  records it, then how the split moved the figures. */
public class AuditClaimSplit {
    public void audit(@Val SplitInput input, @Val Claim claim, @Val Split split, @Val Rollup before, PersonStore people,
            Audit audit, RollupService rollups) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        String who = " sheet=" + claim.getSheetId() + " by=" + input.user() + " person=" + person.getName();
        ClaimResponse shown = ClaimResponse.from(claim);
        audit.record("CLAIM_SPLIT" + who + " amount=" + shown.amount() + " date=" + shown.date()
                + " number=" + claim.getNumber() + " into=" + split.into().getNumber());
        ClaimResponse into = ClaimResponse.from(split.into());
        audit.record(ClaimStatus.OPEN.event() + who + " amount=" + into.amount() + " date=" + into.date()
                + " number=" + split.into().getNumber());
        rollups.record(claim.getSheetId(), input.user(), before);
    }
}

